  return (
    <div id="createObjectContainer"> 
      {/* Asset Selection and Creation */}
      <select id="assetDropdown" value={value}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>{asset}</option> 
        ))}
      </select>
      <button id="createButton" onClick={() => {
        if (value) {
          model.createObject(value).then(() => { 
            model.setSelectedAsset(value); 
          });
        }
      }}>Create Selected Asset</button>

      {/* Display Selected Asset (Dynamically Rendered) */}
      <div id="selectedAssetPreview">{model.selectedAsset && <div id="assetPreview">{model.selectedAsset}</div>}</div>

      {/* Cleanup Button */}
