function reorderAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = words.filter(word => adjectiveDetector(word)); // Utilize an adj detector (see below)
  const reorderedWords = rearrangeAdjectives(adjectives, words);
  return reorderedWords.join(' ');
}

// Helper function: Simple adjective detection (expand for robustness)
function adjectiveDetector(word) {
  // Basic regex, enhance with NLP for accuracy
  return /^[a-zA-Z]+(?:-[a-zA-Z]+)*[aeiou]$/.test(word); 
}

// Logic to rearrange adjectives (flexible approaches)
function rearrangeAdjectives(adjs, originalWords) {
  const adjIndex = originalWords.indexOf(adjs[0]);  // Find initial adjective's position
  const reordered = [...originalWords]; // Clone to modify
  reordered.splice(adjIndex, 0, ...adjs.slice(1)); // Insert remaining adjs before the first
  reordered.splice(adjIndex + 1, 1, adjs[0]);   // Move the first adjective to its new place
  return reordered;
}

// Example usage:
const sentence = "Beautiful green trees are in the park";
const reorderedSentence = reorderAdjectives(sentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park 
```

