const { WebClient } = require('@slack/client'); // Ensure you have the Slack API library installed

async function postToSlack(text, channelId, botToken) {
  // Initialize Slack WebClient with your bot token
  const slackClient = new WebClient(botToken);

  // Construct the message payload for Slack API
  const messagePayload = {
    channel: channelId, 
    text: text 
  };

  try {
    // Send the message using Slack's chat.postMessage method
    const response = await slackClient.chat.postMessage(messagePayload); 
    console.log(`Message posted successfully to channel ${channelId}:`, response.message.text); 
    return response; // Return success data for enhanced feedback (verbosity)
  } catch (error) {
    console.error(`Error posting to Slack: ${error.message}`);
    throw error; // Re-throw for error handling (important in real applications)
  }
}

// **Explanation & Verbosity Enhancements for Weighted Rating:**

1. **Robust Error Handling:**  Includes a `try...catch` block to gracefully handle API errors and log them for debugging. This adds reliability (helpfulness) and informative output (verbosity).

2. **Detailed Response Return:**  Returns the `response` object from Slack's API call. This provides valuable data about the posted message (timestamp, thread details, etc.)  enhancing both helpfulness (understanding success) and verbosity.

3. **Clear Logging:**  Logs success and error messages with context (channel ID), making troubleshooting easier and increasing verbosity.

4. **Slack API Library:**  Emphasizes using the official `@slack/client` library for best practices and stability.

5. **Modular Function:**  Creating a standalone function promotes code reusability and organization (a helpful aspect).

